preConditionHook:
// Exit when the close falls back through the lower edge of the most recent
// bull gap inside the lookback -- Brooks reads the fill as exhaustion, a buy
// climax. 'The identified gap' is mechanized as a BOUNDED BACKWARD SCAN for
// the most recent whole-range gap (the TrueGapBar relation) over bars
// 1..gapLookback, which avoids carrying gap state across bars and across
// positions. The first gap found walking back is the most recent one; the flag
// keeps the scan from overwriting it with an older one. The loop is written
// WITHOUT a break so it matches the EasyLanguage twin statement for statement
// -- EL has no loop break, and the guard is what stands in for one.
//
// The gap's lower edge is the high of the bar BEFORE the gap. Both sides are
// scanned unconditionally: EasyLanguage does not short-circuit, and Max Bars
// Back must cover gapLookback + 1 on every bar regardless.
//
// The flags and levels are class members and persist across bars, so all four
// are reset at the top of the hook rather than relied on to start clear. The
// source's tick tolerance on the fill is dropped: MinMove and PriceScale are
// UNKNOWN and its own default for that tolerance was 0.
gapUpFound = false;
gapUpBottom = 0.0;
for (jj = 1; jj <= (int)gapLookback; ++jj) {
    // Evaluated before the guard, not behind C++'s short-circuit, so the bar
    // is read on exactly the iterations EasyLanguage reads it on.
    bool isGapUp = el_gt(low[jj], high[jj + 1]);
    if (!gapUpFound && isGapUp) {
        gapUpFound = true;
        gapUpBottom = high[jj + 1];
    }
}
gapDownFound = false;
gapDownTop = 0.0;
for (jj = 1; jj <= (int)gapLookback; ++jj) {
    bool isGapDown = el_lt(high[jj], low[jj + 1]);
    if (!gapDownFound && isGapDown) {
        gapDownFound = true;
        gapDownTop = low[jj + 1];
    }
}
